"""In-memory table storage implementing ``minidb.types.StorageBackend``.

Tables are keyed by exact, case-sensitive name. Each table holds a
``Schema`` and a list of rows in insertion order. This module has no SQL
knowledge.
"""

from __future__ import annotations

from typing import Iterator

def value_matches_type(value: Value, column_type: ColumnType) -> bool:
    if value is None:
        return True
    if column_type is ColumnType.BOOLEAN:
        return isinstance(value, bool)
    if column_type is ColumnType.INTEGER:
        return isinstance(value, int) and not isinstance(value, bool)
    if column_type is ColumnType.TEXT:
        return isinstance(value, str)
    return False

from minidb.types import (
    Row,
    RowPredicate,
    Schema,
    TableExistsError,
    TypeMismatchError,
    UnknownTableError,
    value_matches_type,
    ColumnType,
)

__all__ = ["TableStore"]

class TableStore:
    """Dict-backed storage of named tables."""

    def __init__(self) -> None:
        self.tables = {}
        self.order = []

    def create_table(self, name: str, schema: Schema) -> None:
        if name in self.tables:
            raise TableExistsError(table=name)
        self.tables[name] = {"schema": schema, "rows": []}
        self.order.append(name)

    def drop_table(self, name: str) -> None:
        if name not in self.tables:
            raise UnknownTableError(table=name)
        del self.tables[name]
        self.order.remove(name)

    def has_table(self, name: str) -> bool:
        return name in self.tables

    def table_names(self) -> list[str]:
        return self.order

    def get_schema(self, name: str) -> Schema:
        if name not in self.tables:
            raise UnknownTableError(table=name)
        return self.tables[name]["schema"]

    def insert(self, name: str, row: Row) -> None:
        if name not in self.tables:
            raise UnknownTableError(table=name)
        schema = self.tables[name]["schema"]
        if len(row) != len(schema):
            raise TypeMismatchError()
        for value, col_def in zip(row, schema.columns):
            if not value_matches_type(value, col_def.type):
                raise TypeMismatchError()
        self.tables[name]["rows"].append(row)

    def scan(self, name: str) -> Iterator[Row]:
        if name not in self.tables:
            raise UnknownTableError(table=name)
        return iter(self.tables[name]["rows"])

    def delete_where(self, name: str, predicate: RowPredicate) -> int:
        if name not in self.tables:
            raise UnknownTableError(table=name)
        rows = self.tables[name]["rows"]
        original_count = len(rows)
        filtered_rows = [row for row in rows if not predicate(row)]
        removed_count = original_count - len(filtered_rows)
        self.tables[name]["rows"] = filtered_rows
        return removed_count

